mapper.select:
SELECT t.id, t.employee_id as employeeId, e.employee_name as employeeName, t.period_id as periodId, p.settlement_month as settlementMonth, t.item_code as itemCode, t.item_name as itemName, t.adjust_type as adjustType, t.original_amount as originalAmount, t.currency, t.exchange_rate as exchangeRate, t.settlement_amount as settlementAmount, t.status, t.taxable_flag as taxableFlag, t.remark, t.create_by as createBy, t.create_time as createTime FROM salary_adjustment t LEFT JOIN salary_employee e ON t.employee_id = e.id AND e.delete_flag = 0 LEFT JOIN salary_period p ON t.period_id = p.id AND p.delete_flag = 0 t.delete_flag = 0
AND t.employee_id = #{query.employeeId}
AND t.period_id = #{query.periodId}
AND t.status = #{query.status}
AND t.item_code = #{query.itemCode}
ORDER BY t.create_time DESC
